// Port of ManageRecurringTransactionsView.tsx. Instances are generated by the
// server cron (process-recurring-transactions.ts), not by the client.

import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

import '../../core/logic/domain_utils.dart';
import '../../core/models.dart';
import '../../core/store.dart';
import '../../core/ui/category_picker.dart';
import '../../core/ui/theme.dart';
import '../../core/ui/toast.dart';
import '../../core/ui/widgets.dart';
import '../../core/utils/digits.dart';
import '../../core/utils/format.dart';
import '../../core/utils/jalali.dart';
import 'tx_logic.dart';

String formatTelegramMoney(double v, String currency) {
  final usd = currency == 'USD';
  final p = toPersianDigits(formatEnNumber(v.abs(), minFrac: usd ? 2 : 0, maxFrac: usd ? 2 : 0));
  if (usd) return v < 0 ? '−\$$p' : '\$$p';
  return v < 0 ? '−$p تومان' : '$p تومان';
}

class RecurringScreen extends StatefulWidget {
  const RecurringScreen({super.key});
  @override
  State<RecurringScreen> createState() => _RecurringScreenState();
}

class _RecurringScreenState extends State<RecurringScreen> {
  List<RecurringTransaction> rows = [];
  bool loading = true, submitting = false, formOpen = false;
  int formKey = 0;

  String? editingId, walletId, categoryId;
  String title = '', type = 'EXPENSE', amountToman = '', intervalNumber = '1', intervalPeriod = 'month', nextDueDate = '', endDate = '', note = '';
  bool isActive = true;

  SupabaseClient get _c => Supabase.instance.client;

  @override
  void initState() {
    super.initState();
    _emptyForm();
    _refresh();
  }

  void _emptyForm() {
    editingId = walletId = categoryId = null;
    title = amountToman = endDate = note = '';
    type = 'EXPENSE';
    intervalNumber = '1';
    intervalPeriod = 'month';
    nextDueDate = todayStr();
    isActive = true;
    formKey++;
  }

  Future<void> _refresh() async {
    setState(() => loading = true);
    try {
      final data = await _c.from('recurring_transactions').select().isFilter('deleted_at', null).order('next_due_date_string', ascending: true);
      rows = (data as List).cast<Json>().map(RecurringTransaction.fromJson).toList();
    } catch (_) {
      Toast.error('خطا در دریافت تراکنش‌های دوره‌ای.');
    } finally {
      if (mounted) setState(() => loading = false);
    }
  }

  void _reset() => setState(() {
        _emptyForm();
        formOpen = false;
      });

  void _openCreate() => setState(() {
        _emptyForm();
        formOpen = true;
      });

  void _openEdit(RecurringTransaction r) => setState(() {
        editingId = r.id;
        title = r.title;
        type = r.type;
        amountToman = jsNumStr(r.amountToman);
        walletId = r.walletId;
        categoryId = r.categoryId;
        intervalNumber = '${r.intervalNumber}';
        intervalPeriod = r.intervalPeriod;
        nextDueDate = r.nextDueDateString;
        endDate = r.endDateString ?? '';
        note = r.note ?? '';
        isActive = r.isActive;
        formKey++;
        formOpen = true;
      });

  String? _validate() {
    if (title.trim().isEmpty) return 'عنوان الزامی است.';
    if (walletId == null) return 'کیف پول الزامی است.';
    if (categoryId == null) return 'دسته الزامی است.';
    if (parseJalaali(nextDueDate) == null) return 'تاریخ بعدی نامعتبر است.';
    if (endDate.trim().isNotEmpty && parseJalaali(endDate) == null) return 'تاریخ پایان نامعتبر است.';
    final a = n(amountToman);
    if (!a.isFinite || a <= 0) return 'مبلغ نامعتبر است.';
    final i = n(intervalNumber);
    if (!i.isFinite || i <= 0 || i != i.truncateToDouble()) return 'فاصله تکرار نامعتبر است.';
    return null;
  }

  Future<void> _submit(PortfolioStore s) async {
    final user = s.user;
    if (user == null) return;
    final err = _validate();
    if (err != null) {
      Toast.error(err);
      return;
    }
    final payload = {
      'title': title.trim(),
      'type': type,
      'amount_toman': n(amountToman),
      'wallet_id': walletId,
      'category_id': categoryId,
      'interval_number': n(intervalNumber).toInt(),
      'interval_period': intervalPeriod,
      'next_due_date_string': nextDueDate,
      'end_date_string': endDate.trim().isEmpty ? null : endDate.trim(),
      'note': note.trim().isEmpty ? null : note.trim(),
      'is_active': isActive,
      'updated_at': DateTime.now().toUtc().toIso8601String(),
    };
    setState(() => submitting = true);
    try {
      if (editingId != null) {
        await _c.from('recurring_transactions').update(payload).eq('id', editingId!);
        Toast.success('الگو ویرایش شد.');
      } else {
        await _c.from('recurring_transactions').insert({...payload, 'user_id': user.id, 'deleted_at': null});
        Toast.success('تراکنش دوره‌ای ثبت شد.');
      }
      _reset();
      await _refresh();
    } catch (_) {
      Toast.error('خطا در ذخیره.');
    } finally {
      if (mounted) setState(() => submitting = false);
    }
  }

  Future<void> _delete(RecurringTransaction r) async {
    if (!await confirmDialog(context, message: '«${r.title}» حذف شود؟', danger: true, confirmLabel: 'حذف')) return;
    setState(() => submitting = true);
    try {
      await _c.from('recurring_transactions').update({'deleted_at': DateTime.now().toUtc().toIso8601String(), 'is_active': false}).eq('id', r.id);
      Toast.success('حذف شد.');
      if (editingId == r.id) _reset();
      await _refresh();
    } catch (_) {
      Toast.error('خطا در حذف.');
    } finally {
      if (mounted) setState(() => submitting = false);
    }
  }

  Future<void> _toggle(RecurringTransaction r) async {
    setState(() => submitting = true);
    try {
      await _c.from('recurring_transactions').update({'is_active': !r.isActive, 'updated_at': DateTime.now().toUtc().toIso8601String()}).eq('id', r.id);
      await _refresh();
    } catch (_) {
      Toast.error('خطا در تغییر وضعیت.');
    } finally {
      if (mounted) setState(() => submitting = false);
    }
  }

  String _human(String d) {
    final p = parseJalaali(d);
    return p != null ? formatJalaaliHuman(p) : d;
  }

  Widget _form(PortfolioStore s) {
    final w = findWallet(s.wallets, walletId);
    final cat = s.categories.where((c) => c.id == categoryId).firstOrNull;
    return AppCard(
      key: ValueKey(formKey),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Row(children: [
          Expanded(child: Text(editingId != null ? 'ویرایش' : 'الگوی جدید', style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: Colors.white))),
          IconBtn(Icons.close, onTap: _reset),
        ]),
        const SizedBox(height: 10),
        Field(label: 'عنوان', child: AppTextField(value: title, onChanged: (v) => title = v, hint: 'عنوان (مثلا: اجاره)')),
        Padding(
          padding: const EdgeInsets.only(bottom: 14),
          child: Segmented<String>(
            options: const [('EXPENSE', 'هزینه'), ('INCOME', 'درآمد')],
            value: type,
            onChanged: (v) => setState(() {
              type = v;
              categoryId = null;
            }),
          ),
        ),
        Field(label: 'مبلغ (تومان)', child: NumberInput(value: amountToman, onChanged: (v) => amountToman = v)),
        Field(
          label: 'کیف پول',
          child: SelectBox(
            text: w?.name ?? 'انتخاب کنید',
            placeholder: w == null,
            trailing: Icons.chevron_left,
            onTap: () async {
              final r = await showListPicker(context,
                  title: 'انتخاب کیف پول',
                  items: [for (final x in s.wallets) PickItem(id: x.id, label: x.name, sublabel: '${currencyMeta(x.currency).label} · ${x.currency}')],
                  value: walletId);
              if (r != null && r != kNone) setState(() => walletId = r);
            },
          ),
        ),
        Field(
          label: 'دسته',
          child: SelectBox(
            text: categoryId == null ? 'انتخاب کنید' : (cat?.name ?? 'انتخاب'),
            placeholder: categoryId == null,
            trailing: Icons.chevron_left,
            onTap: () async {
              final r = await showCategoryPicker(context, title: 'انتخاب دسته', kind: type == 'INCOME' ? 'income' : 'expense', categories: s.categories, value: categoryId);
              if (r != null && r != kNone) setState(() => categoryId = r);
            },
          ),
        ),
        Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Expanded(child: Field(label: 'هر', child: NumberInput(value: intervalNumber, onChanged: (v) => intervalNumber = v))),
          const SizedBox(width: 10),
          Expanded(
            flex: 2,
            child: Field(
              label: 'واحد',
              child: Segmented<String>(options: [for (final e in kIntervalLabels.entries) (e.key, e.value)], value: intervalPeriod, onChanged: (v) => setState(() => intervalPeriod = v)),
            ),
          ),
        ]),
        Field(label: 'سررسید بعدی', child: DateField(value: nextDueDate, onChanged: (v) => setState(() => nextDueDate = v))),
        Field(
          label: 'پایان (اختیاری)',
          child: Row(children: [
            Expanded(
              child: SelectBox(
                text: endDate.trim().isEmpty ? 'بدون پایان' : toPersianDigits(_human(endDate)),
                placeholder: endDate.trim().isEmpty,
                leading: const Icon(Icons.calendar_today_outlined, size: 16, color: C.slate400),
                onTap: () async {
                  final r = await showJalaliDatePicker(context, endDate.isNotEmpty ? endDate : nextDueDate);
                  if (r != null) setState(() => endDate = r);
                },
              ),
            ),
            if (endDate.isNotEmpty) IconBtn(Icons.close, onTap: () => setState(() => endDate = '')),
          ]),
        ),
        Field(label: 'یادداشت', child: AppTextField(value: note, onChanged: (v) => note = v, maxLines: 2, hint: 'یادداشت (اختیاری)')),
        SwitchRow(title: 'فعال', value: isActive, onChanged: (v) => setState(() => isActive = v)),
        const SizedBox(height: 12),
        AppButton(submitting ? 'در حال ذخیره...' : (editingId != null ? 'ذخیره' : 'ثبت الگو'), expand: true, onPressed: submitting ? null : () => _submit(s)),
      ]),
    );
  }

  @override
  Widget build(BuildContext context) {
    final s = context.watch<PortfolioStore>();
    if (s.user == null) return const SizedBox.shrink();
    return SubPage(
      title: 'تراکنش‌های دوره‌ای',
      actions: [if (!formOpen) TextButton.icon(onPressed: _openCreate, icon: const Icon(Icons.add, size: 16), label: const Text('جدید'))],
      body: RefreshIndicator(
        onRefresh: _refresh,
        child: ListView(padding: const EdgeInsets.fromLTRB(16, 4, 16, 32), children: [
          AppCard(
            padding: const EdgeInsets.all(12),
            color: C.purple500.withValues(alpha: 0.08),
            child: const Text('حقوق، اجاره و … — هر روز ساعت ۹ صبح (تهران) اگر سررسید رسیده باشد، تراکنش خودکار ثبت می‌شود.',
                style: TextStyle(fontSize: 12, color: C.slate300, height: 1.6)),
          ),
          const SizedBox(height: 14),
          if (formOpen) ...[_form(s), const SizedBox(height: 14)],
          if (loading)
            const Padding(padding: EdgeInsets.all(30), child: Center(child: Text('در حال دریافت...', style: TextStyle(color: C.slate500))))
          else if (rows.isEmpty)
            const Padding(padding: EdgeInsets.all(30), child: Center(child: Text('تراکنش دوره‌ای ثبت نشده.', style: TextStyle(color: C.slate500))))
          else
            for (final r in rows) _row(s, r),
        ]),
      ),
    );
  }

  Widget _row(PortfolioStore s, RecurringTransaction r) {
    final w = findWallet(s.wallets, r.walletId);
    final cat = s.categories.where((c) => c.id == r.categoryId).firstOrNull;
    final sub = '${r.type == 'EXPENSE' ? 'هزینه' : 'درآمد'} · ${intervalLabel(r.intervalNumber, r.intervalPeriod)}${cat != null ? ' · ${cat.name}' : ''}${w != null ? ' · ${w.name}' : ''}';
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: AppCard(
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Row(children: [
            Expanded(
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Row(children: [
                  const Icon(Icons.repeat, size: 14, color: C.purple400),
                  const SizedBox(width: 6),
                  Flexible(child: Text(r.title, style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: Colors.white))),
                ]),
                const SizedBox(height: 2),
                Text(sub, style: const TextStyle(fontSize: 11, color: C.slate500)),
              ]),
            ),
            InkWell(
              onTap: submitting ? null : () => _toggle(r),
              borderRadius: BorderRadius.circular(8),
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                decoration: BoxDecoration(color: (r.isActive ? C.emerald : C.slate500).withValues(alpha: 0.15), borderRadius: BorderRadius.circular(8)),
                child: Text(r.isActive ? 'فعال' : 'متوقف', style: TextStyle(fontSize: 10, color: r.isActive ? C.emerald300 : C.slate400)),
              ),
            ),
          ]),
          const SizedBox(height: 8),
          Money(formatTelegramMoney(r.amountToman, 'TOMAN'), style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w700, color: C.slate200)),
          const SizedBox(height: 4),
          Text('سررسید بعدی: ${toPersianDigits(_human(r.nextDueDateString))}', style: const TextStyle(fontSize: 11, color: C.slate400)),
          const SizedBox(height: 8),
          Row(children: [
            Expanded(child: AppButton('ویرایش', icon: Icons.edit_outlined, dense: true, variant: BtnVariant.secondary, onPressed: () => _openEdit(r))),
            const SizedBox(width: 8),
            Expanded(child: AppButton('حذف', icon: Icons.delete_outline, dense: true, variant: BtnVariant.danger, onPressed: submitting ? null : () => _delete(r))),
          ]),
        ]),
      ),
    );
  }
}
